/**
 * Options that control how {@link mapAsync} schedules and cancels work.
 */
export interface MapAsyncOptions {
	/**
	 * The maximum number of mapper calls that may be active at once.
	 *
	 * A mapper remains active until its return value fulfills or rejects. The
	 * value must be a positive integer; values such as `0`, negative numbers,
	 * fractions, `NaN`, and infinities are rejected.
	 */
	concurrency: number;

	/**
	 * A controller used to cancel the operation and notify active mappers.
	 *
	 * If the controller is aborted by the caller, `mapAsync` stops starting new
	 * mapper calls, waits for every active mapper to settle, and rejects with
	 * `abortController.signal.reason`. If a mapper throws or rejects,
	 * `mapAsync` aborts this controller with that error so the other active
	 * mappers can stop cooperatively.
	 *
	 * When omitted, `mapAsync` creates a controller for this invocation.
	 */
	abortController?: AbortController;
}

/**
 * Maps values concurrently while preserving input order and supporting
 * cooperative cancellation.
 *
 * At most `concurrency` mapper calls are active at any time. Calls begin in
 * ascending index order, and the fulfilled result at each index corresponds
 * to the input at that index, regardless of the order in which mapper calls
 * finish.
 *
 * The `signal` passed to the mapper is shared by all calls in this invocation.
 * Mappers should observe it when they perform cancellable work. Aborting the
 * signal prevents new mapper calls, but it cannot forcibly stop a mapper that
 * ignores cancellation. `mapAsync` always waits for every mapper that already
 * started to settle before its returned promise settles. This means
 * `mapAsync` does not leak mapper promises: every promise it starts is settled
 * before the returned promise settles.
 *
 * The first mapper failure or external abort determines the rejection reason.
 * A mapper failure also aborts the shared controller with the same error,
 * allowing other active mappers to terminate early. After a failure or abort,
 * no additional mapper calls are started. If another active mapper later
 * rejects with a different error, that error is logged to `console.error`
 * because it cannot become the returned promise's rejection reason. Rejections
 * that are identical to `signal.reason` are treated as cooperative cancellation
 * and are not logged.
 *
 * @typeParam Input - The type of each input value.
 * @typeParam Output - The awaited type produced for each input value.
 * @param values - Values to map. The array is not modified.
 * @param mapper - Called once for each started value with its value, index, and
 * shared abort signal. It may return an output, a promise, or another thenable.
 * @param options - Concurrency and optional cancellation controller.
 * @returns A promise that fulfills with results in input order.
 * @throws {RangeError} If `options.concurrency` is not a positive integer.
 * @throws The first mapper error, or the abort reason if the supplied
 * controller is aborted before a mapper fails.
 *
 * @example
 * ```ts
 * import { mapAsync } from "@notionhq/workers/alpha/async-utils";
 *
 * const controller = new AbortController();
 *
 * const pages = await mapAsync(
 *   pageIds,
 *   async (pageId, index, signal) => {
 *     const response = await fetch(`/api/pages/${pageId}`, { signal });
 *     if (!response.ok) {
 *       throw new Error(`Page ${index} failed: ${response.status}`);
 *     }
 *     return response.json();
 *   },
 *   { concurrency: 5, abortController: controller },
 * );
 * ```
 */
export async function mapAsync<Input, Output>(
	values: readonly Input[],
	mapper: (value: Input, index: number, signal: AbortSignal) => Output | PromiseLike<Output>,
	{ concurrency, abortController = new AbortController() }: MapAsyncOptions,
): Promise<Output[]> {
	if (!Number.isInteger(concurrency) || concurrency < 1) {
		throw new RangeError("Concurrency must be a positive integer");
	}

	const results: Output[] = [];
	let nextIndex = 0;
	let rejected = false;
	let rejection: unknown;
	const handleAbort = (): void => {
		if (!rejected) {
			rejected = true;
			rejection = abortController.signal.reason;
		}
	};

	if (abortController.signal.aborted) {
		handleAbort();
	} else {
		abortController.signal.addEventListener("abort", handleAbort, { once: true });
	}

	// Workers claim indexes synchronously before awaiting the mapper, so mapper invocation
	// order always matches input order even when mapper completion order does not.
	const worker = async (): Promise<void> => {
		while (!rejected) {
			const index = nextIndex++;

			if (index >= values.length) {
				return;
			}

			try {
				results[index] = await mapper(values[index]!, index, abortController.signal);
			} catch (error) {
				if (!rejected) {
					rejected = true;
					rejection = error;
					abortController.abort(error);
				} else if (error !== abortController.signal.reason) {
					console.error(
						`mapAsync mapper at index ${index} rejected after another failure or abort`,
						error,
					);
				}
			}
		}
	};

	const workers = Array.from({ length: Math.min(concurrency, values.length) }, worker);
	// Mapper failures are captured above, so workers do not reject early. Waiting for all of
	// them here drains every active mapper before the captured failure is rethrown below.
	try {
		await Promise.all(workers);
	} finally {
		abortController.signal.removeEventListener("abort", handleAbort);
	}

	if (rejected) {
		throw rejection;
	}

	return results;
}
